import { BadgeCheck, Box, Star } from 'lucide-react';
import { Link } from 'react-router-dom';
import { formatMarketplacePrice } from '../../lib/marketplace';
import { trackMarketplaceEvent } from '../../lib/marketplaceAnalytics';
import type { MarketplaceListing } from '../../types/marketplace';

const typeLabels: Record<MarketplaceListing['type'], string> = {
  'digital-product': 'Digital product',
  service: 'Service',
  course: 'Course',
  community: 'Community',
};

export const MarketplaceListingCard = ({
  listing,
  eagerImage = false,
}: {
  listing: MarketplaceListing;
  eagerImage?: boolean;
}) => (
  <article className="group h-full min-w-0">
    <Link
      to={listing.href}
      onClick={() =>
        trackMarketplaceEvent('marketplace_listing_opened', {
          listing_id: listing.id,
          listing_type: listing.type,
        })
      }
      className="flex h-full w-full min-w-0 flex-col overflow-hidden rounded-[1.5rem] border border-black/10 bg-white shadow-[0_18px_50px_rgba(0,0,0,0.07)] outline-none transition duration-200 hover:-translate-y-1 hover:border-indigo-400/40 hover:shadow-[0_24px_60px_rgba(0,0,0,0.11)] focus-visible:ring-2 focus-visible:ring-indigo-500 focus-visible:ring-offset-2 focus-visible:ring-offset-[#f6f6f7] dark:border-white/10 dark:bg-[#111111] dark:shadow-[0_18px_50px_rgba(0,0,0,0.28)] dark:hover:border-indigo-400/45 dark:focus-visible:ring-offset-[#070707]"
    >
      <div className="relative aspect-[4/3] overflow-hidden bg-gradient-to-br from-indigo-100 via-slate-100 to-white dark:from-indigo-950/60 dark:via-[#171717] dark:to-[#101010]">
        {listing.imageUrl ? (
          <img
            src={listing.imageUrl}
            alt={`${listing.title} listing image`}
            loading={eagerImage ? 'eager' : 'lazy'}
            decoding="async"
            className="h-full w-full object-cover transition duration-500 group-hover:scale-[1.025]"
            referrerPolicy="no-referrer"
          />
        ) : (
          <div
            className="flex h-full w-full items-center justify-center"
            aria-hidden="true"
          >
            <div className="flex h-16 w-16 items-center justify-center rounded-2xl border border-black/10 bg-white/70 text-indigo-600 shadow-sm dark:border-white/10 dark:bg-white/[0.06] dark:text-indigo-300">
              <Box className="h-7 w-7" />
            </div>
          </div>
        )}
        <span className="absolute left-3 top-3 rounded-full border border-black/10 bg-white/90 px-3 py-1.5 text-[11px] font-semibold text-black shadow-sm backdrop-blur dark:border-white/10 dark:bg-black/70 dark:text-white">
          {typeLabels[listing.type]}
        </span>
      </div>

      <div className="flex flex-1 flex-col p-4 sm:p-5">
        <div className="flex min-w-0 items-center gap-2 text-xs text-neutral-500 dark:text-white/50">
          {listing.seller.avatarUrl ? (
            <img
              src={listing.seller.avatarUrl}
              alt=""
              loading="lazy"
              decoding="async"
              className="h-6 w-6 rounded-full object-cover"
              referrerPolicy="no-referrer"
            />
          ) : (
            <span
              className="flex h-6 w-6 items-center justify-center rounded-full bg-indigo-100 text-[10px] font-bold text-indigo-700 dark:bg-indigo-400/15 dark:text-indigo-200"
              aria-hidden="true"
            >
              {(listing.seller.name || listing.seller.username || 'W')
                .charAt(0)
                .toUpperCase()}
            </span>
          )}
          <span className="truncate">
            {listing.seller.name ||
              listing.seller.username ||
              'Seller details unavailable'}
          </span>
          {listing.seller.verification && (
            <span
              className="inline-flex shrink-0 text-blue-600 dark:text-blue-300"
              aria-label={listing.seller.verification.label}
              title={listing.seller.verification.label}
            >
              <BadgeCheck className="h-4 w-4" />
            </span>
          )}
        </div>

        <h3 className="mt-3 line-clamp-2 text-lg font-semibold leading-snug tracking-[-0.02em] text-neutral-950 dark:text-white">
          {listing.title}
        </h3>
        {(listing.shortDescription || listing.description) && (
          <p className="mt-2 line-clamp-2 text-sm leading-5 text-neutral-600 dark:text-white/55">
            {listing.shortDescription || listing.description}
          </p>
        )}

        {listing.facts.length > 0 && (
          <dl className="mt-4 flex flex-wrap gap-2">
            {listing.facts.map((fact) => (
              <div
                key={`${fact.label}:${fact.value}`}
                className="rounded-lg bg-black/[0.04] px-2.5 py-1.5 text-[11px] text-neutral-600 dark:bg-white/[0.055] dark:text-white/55"
              >
                <dt className="sr-only">{fact.label}</dt>
                <dd>{fact.value}</dd>
              </div>
            ))}
          </dl>
        )}

        <div className="mt-auto flex items-end justify-between gap-3 pt-5">
          <div className="min-w-0">
            {listing.ratingCount > 0 && listing.ratingAverage !== null ? (
              <div className="flex items-center gap-1.5 text-xs font-medium text-neutral-600 dark:text-white/60">
                <Star
                  className="h-3.5 w-3.5 fill-amber-400 text-amber-400"
                  aria-hidden="true"
                />
                <span>
                  {listing.ratingAverage.toFixed(1)} ({listing.ratingCount})
                </span>
              </div>
            ) : (
              <span className="text-xs font-medium text-neutral-500 dark:text-white/45">
                New
              </span>
            )}
          </div>
          <p className="text-right text-sm font-semibold text-neutral-950 dark:text-white">
            {formatMarketplacePrice(listing)}
          </p>
        </div>
      </div>
    </Link>
  </article>
);
