import {
  LayoutDashboard,
  Menu,
  Moon,
  Plus,
  Search,
  ShoppingBag,
  Sun,
  UserRound,
  X,
} from 'lucide-react';
import { useEffect, useRef, useState } from 'react';
import { Link, useLocation, useNavigate } from 'react-router-dom';
import { useAuth } from '../context/AuthContext';
import { useTheme } from '../context/ThemeContext';
import { useCart } from '../lib/cart';
import { SearchDropdown } from './SearchDropdown';

const marketplaceLinks = [
  { label: 'Browse', href: '/search' },
  { label: 'Digital Products', href: '/digital-products' },
  { label: 'Services', href: '/services' },
  { label: 'Courses', href: '/courses' },
  { label: 'Communities', href: '/communities' },
];

export const NavBar = () => {
  const navigate = useNavigate();
  const location = useLocation();
  const { user } = useAuth();
  const { isDark, toggleTheme } = useTheme();
  const { count: cartCount } = useCart();
  const [scrolled, setScrolled] = useState(false);
  const [mobileMenuOpen, setMobileMenuOpen] = useState(false);
  const [searchOpen, setSearchOpen] = useState(false);
  const [searchQuery, setSearchQuery] = useState('');
  const [heroSearchVisible, setHeroSearchVisible] = useState(
    location.pathname === '/',
  );
  const menuButtonRef = useRef<HTMLButtonElement>(null);
  const mobileMenuRef = useRef<HTMLDivElement>(null);
  const searchRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const handleScroll = () => setScrolled(window.scrollY > 16);
    handleScroll();
    window.addEventListener('scroll', handleScroll, { passive: true });
    return () => window.removeEventListener('scroll', handleScroll);
  }, []);

  useEffect(() => {
    if (location.pathname !== '/') {
      setHeroSearchVisible(false);
      return;
    }
    const heroSearch = document.getElementById('marketplace-hero-search');
    if (!heroSearch) {
      setHeroSearchVisible(true);
      return;
    }
    const observer = new IntersectionObserver(
      ([entry]) => setHeroSearchVisible(entry.isIntersecting),
      { threshold: 0.12 },
    );
    observer.observe(heroSearch);
    return () => observer.disconnect();
  }, [location.pathname]);

  useEffect(() => {
    setMobileMenuOpen(false);
    setSearchOpen(false);
  }, [location.pathname, location.search]);

  useEffect(() => {
    const handlePointerDown = (event: MouseEvent) => {
      if (
        searchRef.current &&
        !searchRef.current.contains(event.target as Node)
      ) {
        setSearchOpen(false);
      }
    };
    document.addEventListener('mousedown', handlePointerDown);
    return () => document.removeEventListener('mousedown', handlePointerDown);
  }, []);

  useEffect(() => {
    if (!mobileMenuOpen) return;
    const menu = mobileMenuRef.current;
    const focusable = () =>
      Array.from(
        menu?.querySelectorAll<HTMLElement>(
          'a[href], button:not([disabled]), input:not([disabled])',
        ) || [],
      );
    focusable()[0]?.focus();
    const handleKeyDown = (event: KeyboardEvent) => {
      if (event.key === 'Escape') {
        setMobileMenuOpen(false);
        return;
      }
      if (event.key !== 'Tab') return;
      const elements = focusable();
      if (!elements.length) return;
      const first = elements[0];
      const last = elements[elements.length - 1];
      if (event.shiftKey && document.activeElement === first) {
        event.preventDefault();
        last.focus();
      } else if (!event.shiftKey && document.activeElement === last) {
        event.preventDefault();
        first.focus();
      }
    };
    document.addEventListener('keydown', handleKeyDown);
    document.body.style.overflow = 'hidden';
    return () => {
      document.removeEventListener('keydown', handleKeyDown);
      document.body.style.overflow = '';
      menuButtonRef.current?.focus();
    };
  }, [mobileMenuOpen]);

  const submitSearch = (event: React.FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    const query = searchQuery.trim();
    setSearchOpen(false);
    navigate(query ? `/search?q=${encodeURIComponent(query)}` : '/search');
  };

  const showHeaderSearch = location.pathname !== '/' || !heroSearchVisible;
  const hasHeaderSurface = scrolled || location.pathname !== '/' || !isDark;

  return (
    <header
      className={`fixed inset-x-0 top-0 z-[100] border-b transition duration-200 ${
        hasHeaderSurface
          ? 'border-black/[0.07] bg-white/88 shadow-[0_8px_32px_rgba(0,0,0,0.05)] backdrop-blur-xl dark:border-white/[0.08] dark:bg-[#080808]/88 dark:shadow-[0_8px_32px_rgba(0,0,0,0.24)]'
          : 'border-transparent bg-transparent'
      }`}
    >
      <div className="mx-auto flex h-[72px] max-w-[1440px] items-center gap-4 px-4 sm:px-6 lg:px-8">
        <Link
          to="/"
          aria-label="Wersee marketplace home"
          className="flex min-h-11 shrink-0 items-center gap-2 rounded-full outline-none focus-visible:ring-2 focus-visible:ring-indigo-500"
        >
          <img
            src="/brand/wersee-icon-192.png"
            alt=""
            className="h-9 w-9 rounded-xl object-cover"
          />
          <span className="text-lg font-semibold tracking-[-0.035em] text-neutral-950 dark:text-white">
            Wersee
          </span>
        </Link>

        <nav
          aria-label="Marketplace"
          className="ml-2 hidden min-w-0 items-center gap-1 lg:flex"
        >
          {marketplaceLinks.map((link) => {
            const active =
              location.pathname === link.href ||
              (link.href === '/search' && location.pathname === '/search');
            return (
              <Link
                key={link.href}
                to={link.href}
                aria-current={active ? 'page' : undefined}
                className={`inline-flex min-h-11 items-center rounded-full px-3.5 text-[13px] font-medium outline-none transition focus-visible:ring-2 focus-visible:ring-indigo-500 ${
                  active
                    ? 'bg-black/[0.055] text-neutral-950 dark:bg-white/[0.08] dark:text-white'
                    : 'text-neutral-600 hover:bg-black/[0.035] hover:text-neutral-950 dark:text-white/58 dark:hover:bg-white/[0.05] dark:hover:text-white'
                }`}
              >
                {link.label}
              </Link>
            );
          })}
        </nav>

        <div className="ml-auto hidden min-w-0 flex-1 justify-end xl:flex">
          {showHeaderSearch && (
            <div
              ref={searchRef}
              className="relative mr-2 w-full max-w-[260px]"
            >
              <form onSubmit={submitSearch} role="search">
                <label htmlFor="header-marketplace-search" className="sr-only">
                  Search the Wersee marketplace
                </label>
                <Search className="pointer-events-none absolute left-3.5 top-1/2 h-4 w-4 -translate-y-1/2 text-neutral-400 dark:text-white/35" />
                <input
                  id="header-marketplace-search"
                  type="search"
                  value={searchQuery}
                  onFocus={() => setSearchOpen(true)}
                  onChange={(event) => {
                    setSearchQuery(event.target.value);
                    setSearchOpen(true);
                  }}
                  placeholder="Search marketplace"
                  aria-autocomplete="list"
                  aria-expanded={searchOpen}
                  className="h-11 w-full rounded-full border border-black/10 bg-white/75 pl-10 pr-3 text-sm text-neutral-950 outline-none placeholder:text-neutral-400 focus:border-indigo-500 focus:ring-3 focus:ring-indigo-500/10 dark:border-white/10 dark:bg-white/[0.045] dark:text-white dark:placeholder:text-white/30"
                />
              </form>
              <SearchDropdown
                isOpen={searchOpen}
                query={searchQuery}
                onClose={() => setSearchOpen(false)}
              />
            </div>
          )}
        </div>

        <div className="hidden shrink-0 items-center gap-1 md:flex">
          <Link
            to="/create"
            className="inline-flex min-h-11 items-center gap-2 rounded-full bg-indigo-600 px-4 text-sm font-semibold text-white shadow-[0_8px_24px_rgba(79,70,229,0.22)] transition hover:bg-indigo-500 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-indigo-400 focus-visible:ring-offset-2 focus-visible:ring-offset-white dark:focus-visible:ring-offset-[#080808]"
          >
            <Plus className="h-4 w-4" aria-hidden="true" />
            Create
          </Link>
          <Link
            to="/sell"
            className="inline-flex min-h-11 items-center rounded-full px-3.5 text-sm font-semibold text-neutral-700 hover:bg-black/[0.04] dark:text-white/70 dark:hover:bg-white/[0.05]"
          >
            Sell on Wersee
          </Link>
          {cartCount > 0 && (
            <Link
              to="/checkout"
              aria-label={`Open cart with ${cartCount} ${
                cartCount === 1 ? 'item' : 'items'
              }`}
              className="relative flex h-11 w-11 items-center justify-center rounded-full text-neutral-600 hover:bg-black/[0.04] dark:text-white/60 dark:hover:bg-white/[0.05]"
            >
              <ShoppingBag className="h-5 w-5" />
              <span className="absolute right-0.5 top-0.5 flex h-5 min-w-5 items-center justify-center rounded-full bg-indigo-600 px-1 text-[10px] font-bold text-white">
                {cartCount > 9 ? '9+' : cartCount}
              </span>
            </Link>
          )}
          <button
            type="button"
            onClick={toggleTheme}
            aria-label={isDark ? 'Use light theme' : 'Use dark theme'}
            className="flex h-11 w-11 items-center justify-center rounded-full text-neutral-600 hover:bg-black/[0.04] dark:text-white/60 dark:hover:bg-white/[0.05]"
          >
            {isDark ? <Sun className="h-5 w-5" /> : <Moon className="h-5 w-5" />}
          </button>
          {user ? (
            <Link
              to="/workspace/overview"
              className="inline-flex min-h-11 items-center gap-2 rounded-full bg-neutral-950 px-4 text-sm font-semibold text-white hover:bg-neutral-800 dark:bg-white dark:text-black dark:hover:bg-neutral-200"
            >
              <LayoutDashboard className="h-4 w-4" />
              Workspace
            </Link>
          ) : (
            <Link
              to="/signin"
              className="inline-flex min-h-11 items-center rounded-full bg-neutral-950 px-4 text-sm font-semibold text-white hover:bg-neutral-800 dark:bg-white dark:text-black dark:hover:bg-neutral-200"
            >
              Sign in
            </Link>
          )}
        </div>

        <button
          ref={menuButtonRef}
          type="button"
          onClick={() => setMobileMenuOpen(true)}
          aria-expanded={mobileMenuOpen}
          aria-controls="marketplace-mobile-menu"
          aria-label="Open navigation menu"
          className="ml-auto flex h-11 w-11 items-center justify-center rounded-full border border-black/10 bg-white/70 text-neutral-900 md:hidden dark:border-white/10 dark:bg-white/[0.05] dark:text-white"
        >
          <Menu className="h-5 w-5" />
        </button>
      </div>

      {mobileMenuOpen && (
        <div className="fixed inset-0 z-[160] md:hidden">
          <button
            type="button"
            aria-label="Close navigation menu"
            onClick={() => setMobileMenuOpen(false)}
            className="absolute inset-0 h-full w-full bg-black/65 backdrop-blur-sm"
          />
          <div
            id="marketplace-mobile-menu"
            ref={mobileMenuRef}
            role="dialog"
            aria-modal="true"
            aria-labelledby="mobile-menu-title"
            className="absolute inset-x-3 top-3 max-h-[calc(100dvh-1.5rem)] overflow-y-auto rounded-[1.5rem] bg-white p-4 text-neutral-950 shadow-2xl dark:bg-[#111] dark:text-white"
          >
            <div className="flex items-center justify-between">
              <h2 id="mobile-menu-title" className="text-lg font-semibold">
                Marketplace
              </h2>
              <button
                type="button"
                onClick={() => setMobileMenuOpen(false)}
                aria-label="Close navigation menu"
                className="flex h-11 w-11 items-center justify-center rounded-full border border-black/10 dark:border-white/10"
              >
                <X className="h-5 w-5" />
              </button>
            </div>

            <form onSubmit={submitSearch} role="search" className="relative mt-4">
              <label htmlFor="mobile-marketplace-search" className="sr-only">
                Search the Wersee marketplace
              </label>
              <Search className="pointer-events-none absolute left-4 top-1/2 h-5 w-5 -translate-y-1/2 text-neutral-400" />
              <input
                id="mobile-marketplace-search"
                type="search"
                value={searchQuery}
                onChange={(event) => setSearchQuery(event.target.value)}
                placeholder="Search marketplace"
                className="h-13 w-full rounded-xl border border-black/10 bg-neutral-50 pl-12 pr-4 text-base outline-none focus:border-indigo-500 dark:border-white/10 dark:bg-white/[0.05] dark:text-white"
              />
            </form>

            <nav aria-label="Mobile marketplace navigation" className="mt-4 grid gap-1">
              {marketplaceLinks.map((link) => (
                <Link
                  key={link.href}
                  to={link.href}
                  className="flex min-h-12 items-center rounded-full px-4 text-base font-medium hover:bg-black/[0.04] dark:hover:bg-white/[0.05]"
                >
                  {link.label}
                </Link>
              ))}
            </nav>

            <div className="mt-4 grid gap-2 border-t border-black/8 pt-4 dark:border-white/10">
              <Link
                to="/create"
                className="flex min-h-12 items-center justify-center gap-2 rounded-full bg-indigo-600 px-4 text-sm font-semibold text-white shadow-[0_8px_24px_rgba(79,70,229,0.2)] hover:bg-indigo-500"
              >
                <Plus className="h-4 w-4" aria-hidden="true" />
                Create
              </Link>
              <Link
                to="/sell"
                className="flex min-h-12 items-center rounded-full border border-black/10 px-4 text-sm font-semibold dark:border-white/10"
              >
                Sell on Wersee
              </Link>
              {cartCount > 0 && (
                <Link
                  to="/checkout"
                  className="flex min-h-12 items-center justify-between rounded-full border border-black/10 px-4 text-sm font-semibold dark:border-white/10"
                >
                  <span className="flex items-center gap-2">
                    <ShoppingBag className="h-4 w-4" />
                    Cart
                  </span>
                  <span>{cartCount}</span>
                </Link>
              )}
              <button
                type="button"
                onClick={toggleTheme}
                className="flex min-h-12 items-center gap-2 rounded-full border border-black/10 px-4 text-left text-sm font-semibold dark:border-white/10"
              >
                {isDark ? <Sun className="h-4 w-4" /> : <Moon className="h-4 w-4" />}
                {isDark ? 'Use light theme' : 'Use dark theme'}
              </button>
              <Link
                to={user ? '/workspace/overview' : '/signin'}
                className="flex min-h-12 items-center justify-center gap-2 rounded-full bg-neutral-950 px-4 text-sm font-semibold text-white dark:bg-white dark:text-black"
              >
                {user ? (
                  <>
                    <LayoutDashboard className="h-4 w-4" /> Open workspace
                  </>
                ) : (
                  <>
                    <UserRound className="h-4 w-4" /> Sign in
                  </>
                )}
              </Link>
            </div>
          </div>
        </div>
      )}
    </header>
  );
};
