import { useEffect, useMemo, useState } from 'react';
import {
  ArrowRight,
  BookOpen,
  Boxes,
  CheckCircle2,
  GraduationCap,
  Search,
  ShieldCheck,
  Store,
  UsersRound,
  WalletCards,
} from 'lucide-react';
import { Link, useNavigate } from 'react-router-dom';
import { SEO } from '../components/SEO';
import {
  MarketplaceEmptyState,
  MarketplaceErrorState,
  MarketplaceGridSkeleton,
  MarketplaceListingGrid,
} from '../components/marketplace/MarketplaceListingGrid';
import {
  categoryKeyForListing,
  fetchMarketplaceListings,
  MARKETPLACE_CATEGORY_DEFINITIONS,
} from '../lib/marketplace';
import { trackMarketplaceEvent } from '../lib/marketplaceAnalytics';
import type {
  MarketplaceCategoryKey,
  MarketplaceListing,
} from '../types/marketplace';

const categoryIcons = {
  'digital-products': Boxes,
  services: Store,
  courses: GraduationCap,
  communities: UsersRound,
};

const trustItems = [
  {
    title: 'Clear pricing',
    description: 'Review the listed price and billing cadence before checkout.',
    href: '/buyer-protection',
    icon: WalletCards,
  },
  {
    title: 'Seller details',
    description: 'See who offers each product, service, course or membership.',
    href: '/guidelines',
    icon: Store,
  },
  {
    title: 'Secure checkout',
    description: 'Eligible purchases are completed through Wersee’s Stripe checkout.',
    href: '/buyer-protection',
    icon: ShieldCheck,
  },
  {
    title: 'Support when needed',
    description: 'Find purchase guidance and contact support from one place.',
    href: '/support',
    icon: CheckCircle2,
  },
];

const buyingSteps = [
  {
    title: 'Find the right offer',
    description:
      'Search or browse products, services, courses and communities.',
  },
  {
    title: 'Review the details',
    description:
      'Check the price, billing terms, delivery information and seller details.',
  },
  {
    title: 'Pay and receive access',
    description:
      'Complete checkout and manage your purchase through Wersee.',
  },
];

const collectionDefinitions: Array<{
  key: MarketplaceCategoryKey;
  title: string;
  href: string;
}> = [
  {
    key: 'digital-products',
    title: 'Digital tools for creators',
    href: '/digital-products',
  },
  {
    key: 'services',
    title: 'Services to grow your business',
    href: '/services',
  },
  {
    key: 'courses',
    title: 'Learn something new',
    href: '/courses',
  },
  {
    key: 'communities',
    title: 'Communities to join',
    href: '/communities',
  },
];

export const Home = () => {
  const navigate = useNavigate();
  const [query, setQuery] = useState('');
  const [listings, setListings] = useState<MarketplaceListing[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');
  const [attempt, setAttempt] = useState(0);

  useEffect(() => {
    trackMarketplaceEvent('marketplace_view', { surface: 'home' });
  }, []);

  useEffect(() => {
    let active = true;
    setLoading(true);
    setError('');
    void fetchMarketplaceListings({ limit: 48 })
      .then(({ listings: result }) => {
        if (active) setListings(result);
      })
      .catch(() => {
        if (active) {
          setListings([]);
          setError('Published listings could not be retrieved. No placeholder inventory is shown.');
        }
      })
      .finally(() => {
        if (active) setLoading(false);
      });
    return () => {
      active = false;
    };
  }, [attempt]);

  const featuredListings = useMemo(
    () => listings.filter((listing) => listing.featured).slice(0, 8),
    [listings],
  );
  const primaryListings = (
    featuredListings.length ? featuredListings : listings
  ).slice(0, 8);
  const primaryTitle = featuredListings.length
    ? 'Featured by Wersee'
    : 'New on Wersee';
  const collections = useMemo(
    () =>
      collectionDefinitions
        .map((definition) => ({
          ...definition,
          listings: listings
            .filter(
              (listing) => categoryKeyForListing(listing) === definition.key,
            )
            .filter(
              (listing) =>
                !primaryListings.some((primary) => primary.id === listing.id),
            )
            .slice(0, 4),
        }))
        .filter((collection) => collection.listings.length)
        .slice(0, 3),
    [listings, primaryListings],
  );

  const submitSearch = (event: React.FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    const trimmed = query.trim();
    trackMarketplaceEvent('marketplace_search_submitted', {
      surface: 'home',
      has_query: Boolean(trimmed),
    });
    navigate(trimmed ? `/search?q=${encodeURIComponent(trimmed)}` : '/search');
  };

  const websiteJsonLd = {
    '@context': 'https://schema.org',
    '@type': 'WebSite',
    name: 'Wersee',
    url: 'https://www.wersee.com/',
    potentialAction: {
      '@type': 'SearchAction',
      target: 'https://www.wersee.com/search?q={search_term_string}',
      'query-input': 'required name=search_term_string',
    },
  };
  const organizationJsonLd = {
    '@context': 'https://schema.org',
    '@type': 'Organization',
    name: 'Wersee',
    url: 'https://www.wersee.com/',
    logo: 'https://www.wersee.com/brand/wersee-icon-512.png',
  };

  return (
    <div className="home-page bg-[#f6f6f7] text-neutral-950 dark:bg-[#070707] dark:text-white">
      <SEO
        title="Wersee Marketplace — Digital Products, Services, Courses & Communities"
        description="Discover digital products, expert services, courses and communities from independent creators on Wersee."
        url="/"
        jsonLd={[websiteJsonLd, organizationJsonLd]}
      />

      <section className="relative overflow-hidden border-b border-black/[0.06] px-4 pb-14 pt-28 dark:border-white/[0.07] sm:px-6 sm:pb-16 sm:pt-32 lg:px-8">
        <div
          className="pointer-events-none absolute inset-0 bg-[radial-gradient(ellipse_at_top,rgba(79,70,229,0.15),transparent_56%)] dark:bg-[radial-gradient(ellipse_at_top,rgba(79,70,229,0.18),transparent_58%)]"
          aria-hidden="true"
        />
        <div className="relative mx-auto max-w-[1440px]">
          <div className="max-w-5xl">
            <p className="text-sm font-semibold text-indigo-600 dark:text-indigo-300">
              Where the internet does business
            </p>
            <h1 className="mt-4 max-w-5xl text-[clamp(2.35rem,6vw,5rem)] font-semibold leading-[0.98] tracking-[-0.055em] text-neutral-950 dark:text-[#f5f5f7]">
              Find digital products, expert services, courses and communities.
            </h1>
            <p className="mt-5 max-w-3xl text-base leading-7 text-neutral-600 dark:text-white/58 sm:text-lg">
              Discover independent creators, compare clear prices and delivery
              terms, and find what you need in one marketplace.
            </p>
          </div>

          <form
            id="marketplace-hero-search"
            onSubmit={submitSearch}
            className="mt-7 flex max-w-4xl flex-col gap-3 sm:flex-row"
            role="search"
          >
            <label htmlFor="marketplace-home-search" className="sr-only">
              Search the Wersee marketplace
            </label>
            <div className="relative min-w-0 flex-1">
              <Search
                className="pointer-events-none absolute left-5 top-1/2 h-5 w-5 -translate-y-1/2 text-neutral-400 dark:text-white/35"
                aria-hidden="true"
              />
              <input
                id="marketplace-home-search"
                type="search"
                value={query}
                onChange={(event) => setQuery(event.target.value)}
                placeholder="Search templates, design services, courses, communities…"
                className="h-16 w-full rounded-2xl border border-black/10 bg-white pl-14 pr-5 text-base text-neutral-950 shadow-[0_18px_55px_rgba(0,0,0,0.08)] outline-none placeholder:text-neutral-400 focus:border-indigo-500 focus:ring-4 focus:ring-indigo-500/10 dark:border-white/12 dark:bg-[#111] dark:text-white dark:shadow-[0_18px_55px_rgba(0,0,0,0.3)] dark:placeholder:text-white/35"
              />
            </div>
            <button
              type="submit"
              className="inline-flex h-16 min-w-32 items-center justify-center gap-2 rounded-2xl bg-indigo-600 px-7 text-base font-semibold text-white outline-none transition hover:bg-indigo-500 focus-visible:ring-2 focus-visible:ring-indigo-400 focus-visible:ring-offset-2 focus-visible:ring-offset-[#f6f6f7] dark:focus-visible:ring-offset-[#070707]"
            >
              Search <ArrowRight className="h-4 w-4" />
            </button>
          </form>
          <a
            href="#marketplace-categories"
            className="mt-4 inline-flex min-h-11 items-center gap-2 text-sm font-semibold text-neutral-600 outline-none hover:text-indigo-600 focus-visible:ring-2 focus-visible:ring-indigo-500 dark:text-white/55 dark:hover:text-white"
          >
            Browse categories <ArrowRight className="h-4 w-4" />
          </a>
        </div>
      </section>

      <main>
        <section
          id="marketplace-categories"
          className="mx-auto max-w-[1440px] scroll-mt-24 px-4 py-12 sm:px-6 lg:px-8 lg:py-16"
          aria-labelledby="category-heading"
        >
          <div className="flex items-end justify-between gap-6">
            <div>
              <p className="text-sm font-medium text-indigo-600 dark:text-indigo-300">
                Browse
              </p>
              <h2
                id="category-heading"
                className="mt-2 text-3xl font-semibold tracking-[-0.035em] sm:text-4xl"
              >
                Start with a category
              </h2>
            </div>
            <Link
              to="/search"
              className="hidden min-h-11 items-center gap-2 text-sm font-semibold text-neutral-600 hover:text-indigo-600 dark:text-white/55 dark:hover:text-white sm:inline-flex"
            >
              View all listings <ArrowRight className="h-4 w-4" />
            </Link>
          </div>
          <div className="mt-7 grid gap-4 sm:grid-cols-2 xl:grid-cols-4">
            {MARKETPLACE_CATEGORY_DEFINITIONS.map((category) => {
              const Icon = categoryIcons[category.key];
              return (
                <Link
                  key={category.key}
                  to={category.href}
                  onClick={() =>
                    trackMarketplaceEvent('marketplace_category_selected', {
                      category: category.key,
                      surface: 'home',
                    })
                  }
                  className="group min-h-52 rounded-[1.6rem] border border-black/8 bg-white p-6 outline-none transition hover:-translate-y-1 hover:border-indigo-500/35 hover:shadow-[0_20px_60px_rgba(0,0,0,0.08)] focus-visible:ring-2 focus-visible:ring-indigo-500 focus-visible:ring-offset-2 focus-visible:ring-offset-[#f6f6f7] dark:border-white/10 dark:bg-[#111] dark:hover:border-indigo-400/40 dark:focus-visible:ring-offset-[#070707]"
                >
                  <span className="flex h-12 w-12 items-center justify-center rounded-2xl bg-indigo-50 text-indigo-600 dark:bg-indigo-400/10 dark:text-indigo-300">
                    <Icon className="h-5 w-5" />
                  </span>
                  <h3 className="mt-7 text-xl font-semibold tracking-[-0.02em]">
                    {category.label}
                  </h3>
                  <p className="mt-2 text-sm leading-6 text-neutral-600 dark:text-white/52">
                    {category.description}
                  </p>
                  <ArrowRight className="mt-5 h-4 w-4 text-indigo-600 transition group-hover:translate-x-1 dark:text-indigo-300" />
                </Link>
              );
            })}
          </div>
        </section>

        <section className="border-y border-black/[0.06] bg-white/60 dark:border-white/[0.07] dark:bg-white/[0.018]">
          <div className="mx-auto grid max-w-[1440px] gap-6 px-4 py-8 sm:grid-cols-2 sm:px-6 lg:grid-cols-4 lg:px-8">
            {trustItems.map((item) => (
              <Link
                key={item.title}
                to={item.href}
                className="group flex min-h-24 items-start gap-3 rounded-xl p-2 outline-none focus-visible:ring-2 focus-visible:ring-indigo-500"
              >
                <item.icon className="mt-0.5 h-5 w-5 shrink-0 text-indigo-600 dark:text-indigo-300" />
                <span>
                  <span className="block text-sm font-semibold">{item.title}</span>
                  <span className="mt-1 block text-xs leading-5 text-neutral-600 dark:text-white/48">
                    {item.description}
                  </span>
                </span>
              </Link>
            ))}
          </div>
        </section>

        <section
          className="mx-auto max-w-[1440px] px-4 py-14 sm:px-6 lg:px-8 lg:py-20"
          aria-labelledby="new-listings-heading"
        >
          <div className="mb-7 flex items-end justify-between gap-5">
            <div>
              <p className="text-sm font-medium text-indigo-600 dark:text-indigo-300">
                Marketplace
              </p>
              <h2
                id="new-listings-heading"
                className="mt-2 text-3xl font-semibold tracking-[-0.035em] sm:text-4xl"
              >
                {primaryTitle}
              </h2>
            </div>
            <Link
              to="/search?sort=newest"
              className="inline-flex min-h-11 items-center gap-2 text-sm font-semibold text-neutral-600 hover:text-indigo-600 dark:text-white/55 dark:hover:text-white"
            >
              Browse all <ArrowRight className="h-4 w-4" />
            </Link>
          </div>
          {loading ? (
            <MarketplaceGridSkeleton />
          ) : error ? (
            <MarketplaceErrorState
              message={error}
              onRetry={() => setAttempt((value) => value + 1)}
            />
          ) : primaryListings.length ? (
            <MarketplaceListingGrid listings={primaryListings} />
          ) : (
            <MarketplaceEmptyState />
          )}
        </section>

        {!loading &&
          !error &&
          collections.map((collection) => (
            <section
              key={collection.key}
              className="mx-auto max-w-[1440px] px-4 pb-16 sm:px-6 lg:px-8"
              aria-labelledby={`collection-${collection.key}`}
            >
              <div className="mb-6 flex items-center justify-between gap-4">
                <h2
                  id={`collection-${collection.key}`}
                  className="text-2xl font-semibold tracking-[-0.025em] sm:text-3xl"
                >
                  {collection.title}
                </h2>
                <Link
                  to={collection.href}
                  className="inline-flex min-h-11 items-center gap-2 text-sm font-semibold text-neutral-600 hover:text-indigo-600 dark:text-white/55 dark:hover:text-white"
                >
                  View category <ArrowRight className="h-4 w-4" />
                </Link>
              </div>
              <MarketplaceListingGrid listings={collection.listings} />
            </section>
          ))}

        <section className="border-y border-black/[0.06] bg-white dark:border-white/[0.07] dark:bg-[#0c0c0c]">
          <div className="mx-auto max-w-[1440px] px-4 py-16 sm:px-6 lg:px-8 lg:py-20">
            <p className="text-sm font-medium text-indigo-600 dark:text-indigo-300">
              A straightforward purchase
            </p>
            <h2 className="mt-2 text-3xl font-semibold tracking-[-0.035em] sm:text-4xl">
              How buying works
            </h2>
            <ol className="mt-9 grid gap-5 md:grid-cols-3">
              {buyingSteps.map((step, index) => (
                <li
                  key={step.title}
                  className="rounded-[1.5rem] border border-black/8 bg-[#fafafa] p-6 dark:border-white/10 dark:bg-white/[0.03]"
                >
                  <span className="flex h-9 w-9 items-center justify-center rounded-full bg-indigo-600 text-sm font-semibold text-white">
                    {index + 1}
                  </span>
                  <h3 className="mt-6 text-xl font-semibold">{step.title}</h3>
                  <p className="mt-2 text-sm leading-6 text-neutral-600 dark:text-white/52">
                    {step.description}
                  </p>
                </li>
              ))}
            </ol>
          </div>
        </section>

        <section className="mx-auto max-w-[1440px] px-4 py-14 sm:px-6 lg:px-8 lg:py-20">
          <div className="overflow-hidden rounded-[1.9rem] bg-neutral-950 px-6 py-10 text-white sm:px-10 sm:py-12 lg:flex lg:items-end lg:justify-between lg:gap-12 lg:px-14">
            <div className="max-w-3xl">
              <BookOpen className="h-6 w-6 text-indigo-300" />
              <h2 className="mt-5 text-3xl font-semibold tracking-[-0.035em] sm:text-4xl">
                Have something valuable to sell?
              </h2>
              <p className="mt-4 text-base leading-7 text-white/60">
                Create a storefront for products, services, courses or
                memberships, then manage payments, customers and delivery from
                one workspace.
              </p>
            </div>
            <div className="mt-8 flex flex-wrap gap-3 lg:mt-0 lg:shrink-0">
              <Link
                to="/sell"
                onClick={() =>
                  trackMarketplaceEvent('seller_cta_clicked', {
                    surface: 'home',
                    action: 'start-selling',
                  })
                }
                className="inline-flex min-h-12 items-center gap-2 rounded-xl bg-white px-5 text-sm font-semibold text-black hover:bg-neutral-200"
              >
                Start selling <ArrowRight className="h-4 w-4" />
              </Link>
              <Link
                to="/sell#how-it-works"
                className="inline-flex min-h-12 items-center rounded-xl border border-white/15 px-5 text-sm font-semibold text-white hover:bg-white/10"
              >
                See how Wersee works
              </Link>
            </div>
          </div>
        </section>
      </main>
    </div>
  );
};
